CREATE TABLE tournament (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL, event_date DATE NOT NULL, venue VARCHAR(200) NOT NULL, draw_seed BIGINT);
CREATE TABLE category (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tournament_id BIGINT NOT NULL REFERENCES tournament(id), name VARCHAR(160) NOT NULL, sex VARCHAR(8) NOT NULL, min_age INT NOT NULL, max_age INT NOT NULL, min_weight NUMERIC(6,2) NOT NULL, max_weight NUMERIC(6,2) NOT NULL, min_belt INT NOT NULL, max_belt INT NOT NULL);
CREATE TABLE athlete (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tournament_id BIGINT NOT NULL REFERENCES tournament(id), name VARCHAR(160) NOT NULL, club VARCHAR(160) NOT NULL, birth_date DATE NOT NULL, sex VARCHAR(8) NOT NULL, weight NUMERIC(6,2) NOT NULL, belt INT NOT NULL);
CREATE TABLE bout (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES category(id), round_number INT NOT NULL, position INT NOT NULL, red_id BIGINT REFERENCES athlete(id), blue_id BIGINT REFERENCES athlete(id), winner_id BIGINT REFERENCES athlete(id), resolved BOOLEAN NOT NULL DEFAULT FALSE, automatic BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(category_id, round_number, position));
CREATE INDEX athlete_tournament ON athlete(tournament_id);
CREATE INDEX category_tournament ON category(tournament_id);
